#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU.
#
# Reporting rules (HANDOFF.md):
#   - One line per SKU that appears in the day's movements.log, no other lines.
#   - A line is printed even when net movements cancel to zero.
#   - Every catalog SKU must appear, including SKUs with no movements that day.
#     SKU-9 is in the catalog.

# Catalog SKUs that must appear even if they have no movements that day.
catalog="SKU-9"

{
    awk '
        BEGIN { for (i = 1; i <= split(ENVIRON["catalog"], c, " "); i++) have[c[i]] = 1 }
        {
            net[$1] += ($2 == "receipt" ? $3 : -$3)
            seen[$1] = 1
            if (!($1 in have)) have[$1] = 1   # any logged SKU gets a line
        }
        END {
            for (sku in have) print sku, (sku in net ? net[sku] : 0)
        }
    ' catalog="$catalog" movements.log
} | sort > stock.txt

#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU.
#
# Reporting rules (HANDOFF.md):
#   - One line per SKU that appears in the day's movements.log, no other lines.
#   - A line is printed even when net movements cancel to zero.
#   - Every catalog SKU must appear, including SKUs with no movements that day.
#     SKU-9 is in the catalog.

# Catalog SKUs that must appear even if they have no movements that day.
catalog="SKU-9"

{
    # Pass the catalog through the environment so it is visible in BEGIN
    # (a `var=value` argv would be applied after the input file under POSIX awk).
    catalog="$catalog" awk '
        BEGIN { for (i = 1; i <= split(ENVIRON["catalog"], c, " "); i++) have[c[i]] = 1 }
        {
            net[$1] += ($2 == "receipt" ? $3 : -$3)
            have[$1] = 1   # any SKU that appears in the log gets a line
        }
        END {
            for (sku in have) print sku, (sku in net ? net[sku] : 0)
        }
    ' movements.log
} | sort > stock.txt
